// Recibo de abono (HU-02).
//
// `datos.importe` es lo que se acaba de abonar y `datos.pendiente` lo que queda.
// Los dos salen de la API de la tienda: aqui no se recalcula nada.
// Si el apartado queda liquidado, el mensaje es otro: puede recoger sus zapatos.
const entrada = $input.first().json ?? {};
const d = entrada.datos ?? entrada;

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = (s) => '<p>' + escapar(s).replace(/\n/g, '<br>') + '</p>';

const emailTienda = $vars.EMAIL_MARISA || 'marisa@pasofirme.example';
const producto = [d.producto, d.talla].filter(Boolean).join(' · ');
const liquidado = String(d.estado ?? '') === 'liquidado';

const cuerpoCliente = liquidado
  ? [
      'Hola ' + (d.cliente ?? '') + ',',
      '',
      'Gracias! Hemos recibido tu abono de ' + euros(d.importe) + '.',
      '',
      'Apartado: ' + producto,
      'Total del apartado: ' + euros(d.precio),
      'Abonado: ' + euros(d.abonado),
      'Pendiente: ' + euros(d.pendiente),
      '',
      'Ya lo tienes pagado: puedes pasar por la tienda a recoger tus zapatos.',
      '',
      'Gracias!',
      'Zapateria Paso Firme',
    ].join('\n')
  : [
      'Hola ' + (d.cliente ?? '') + ',',
      '',
      'Gracias! Hemos recibido tu abono de ' + euros(d.importe) + '.',
      '',
      'Apartado: ' + producto,
      'Abonado: ' + euros(d.abonado),
      'Te queda por pagar: ' + euros(d.pendiente),
      'Fecha limite: ' + (d.fecha_limite ?? ''),
      '',
      'Un saludo,',
      'Zapateria Paso Firme',
    ].join('\n');

const cuerpoTienda = [
  'No se ha podido mandar el recibo del abono del apartado #' + (d.id ?? '') + ' (' + (d.cliente ?? '') + '): no tiene correo electronico.',
  '',
  'Abono recibido: ' + euros(d.importe),
  'Abonado: ' + euros(d.abonado),
  'Pendiente: ' + euros(d.pendiente),
].join('\n');

const emailCliente = String(d.email ?? '').trim();
const esCliente = emailCliente.length > 0;

const mensaje = esCliente
  ? { canal: 'email', email: emailCliente, asunto: 'Recibo de tu abono · Paso Firme', cuerpo: cuerpoCliente }
  : { canal: 'email', email: emailTienda, asunto: 'Abono sin recibo · Apartado #' + (d.id ?? ''), cuerpo: cuerpoTienda };

return [{
  json: {
    ...mensaje,
    cuerpo_html: html(mensaje.cuerpo),
    liquidado,
    avisado_al_cliente: esCliente,
    apartado_id: d.id ?? null,
  },
}];
